{
  "tools": [
    {
      "name": "asset_info",
      "title": "Asset Info",
      "toolset": "asset",
      "description": "Everything about one asset - name, type, source and compiled file paths, compile state, tags, cloud package, and how many assets it references and is used by. Explore those relationships with asset_dependencies.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Asset path, as returned by asset_search. Absolute paths work too."
          }
        },
        "required": [
          "path"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Name": {
            "type": "string"
          },
          "Path": {
            "type": "string"
          },
          "Type": {
            "type": "string"
          },
          "Extension": {
            "type": "string"
          },
          "IsGameResource": {
            "type": "boolean"
          },
          "SourceFile": {
            "type": "string"
          },
          "CompiledFile": {
            "type": "string"
          },
          "IsCompiled": {
            "type": "boolean"
          },
          "IsCompiledAndUpToDate": {
            "type": "boolean"
          },
          "IsCompileFailed": {
            "type": "boolean"
          },
          "CanRecompile": {
            "type": "boolean"
          },
          "IsCloud": {
            "type": "boolean"
          },
          "IsTransient": {
            "type": "boolean"
          },
          "IsProcedural": {
            "type": "boolean"
          },
          "IsTrivialChild": {
            "type": "boolean"
          },
          "Package": {
            "type": "string"
          },
          "Tags": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "ReferenceCount": {
            "type": "integer"
          },
          "DependantCount": {
            "type": "integer"
          },
          "LastOpened": {
            "type": "string"
          }
        },
        "required": []
      }
    },
    {
      "name": "find_packages",
      "title": "Find Packages",
      "toolset": "package",
      "description": "Search the backend for published packages - models, gamemodes, maps, addons. Plain words search text, and the query supports filters like 'type:model', 'type:gamemode', 'tag:fun' and 'sort:popular' mixed in with the search words.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Search query, e.g. 'barrel type:model sort:popular'."
          },
          "limit": {
            "type": "integer",
            "description": "How many results to return.",
            "minimum": 1,
            "maximum": 100,
            "default": 20
          },
          "offset": {
            "type": "integer",
            "description": "How many results to skip, for paging.",
            "default": 0
          }
        },
        "required": [
          "query"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "TotalCount": {
            "type": "integer",
            "description": "How many packages matched in total, beyond this page."
          },
          "Packages": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Ident": {
                  "type": "string",
                  "description": "The ident get_package and install_package take."
                },
                "Title": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                },
                "Org": {
                  "type": "string"
                },
                "Summary": {
                  "type": "string"
                },
                "Tags": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                },
                "VotesUp": {
                  "type": "integer"
                },
                "Updated": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "get_package",
      "title": "Get Package",
      "toolset": "package",
      "description": "Fetch a single package from the backend by ident - full details including description, tags, votes, usage stats and timestamps. Use this after find_packages to dig into one result.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "ident": {
            "type": "string",
            "description": "The package ident, like 'facepunch.sandbox' or from find_packages."
          }
        },
        "required": [
          "ident"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Ident": {
            "type": "string"
          },
          "Title": {
            "type": "string"
          },
          "Type": {
            "type": "string"
          },
          "Org": {
            "type": "object",
            "properties": {
              "Ident": {
                "type": "string"
              },
              "Title": {
                "type": "string"
              }
            },
            "required": []
          },
          "Summary": {
            "type": "string"
          },
          "Description": {
            "type": "string"
          },
          "Tags": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "Public": {
            "type": "boolean"
          },
          "Archived": {
            "type": "boolean"
          },
          "Favourited": {
            "type": "integer"
          },
          "VotesUp": {
            "type": "integer"
          },
          "VotesDown": {
            "type": "integer"
          },
          "EngineVersion": {
            "type": "string"
          },
          "Created": {
            "type": "string"
          },
          "Updated": {
            "type": "string"
          }
        },
        "required": []
      }
    },
    {
      "name": "install_package",
      "title": "Install Package",
      "toolset": "package",
      "description": "Download and install a cloud package into the project so its assets can be used - after this the returned asset path works anywhere an asset path does, e.g. spawn_model for a model package. Already-installed packages return immediately.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "ident": {
            "type": "string",
            "description": "The package ident, like 'facepunch.wooden_crate' or from find_packages."
          }
        },
        "required": [
          "ident"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Ident": {
            "type": "string"
          },
          "AssetPath": {
            "type": "string",
            "description": "The primary asset's path - works anywhere an asset path does."
          },
          "AssetType": {
            "type": "string"
          }
        },
        "required": []
      }
    }
  ],
  "total": 128
}
